t.script:
document.addEventListener('DOMContentLoaded', function () {
  // 1) Transformar el bloc d'informació personal en <details>
  const detalls = document.querySelector('.o_portal_my_details');
  if (detalls) {
    const details = document.createElement('details');
    const summary = document.createElement('summary');
    summary.innerText = '👥 Informació personal'; // icona unisex
    summary.className = 'card-header h5 mb-0 text-primary';
    details.className = 'card mb-4';
    details.appendChild(summary);

    const cloned = detalls.cloneNode(true);
    details.appendChild(cloned);
    detalls.replaceWith(details);
  }

  // 2) Canviar "Pressupostos" -> "📅 Reserves" a l'enllaç /my/quotes
  const quotesA = document.querySelector("a[href='/my/quotes']");
  if (quotesA) {
    let changedText = false;
    quotesA.childNodes.forEach(n => {
      if (n.nodeType === Node.TEXT_NODE && n.nodeValue.trim()) {
        n.nodeValue = "📅 Reserves ";
        changedText = true;
      }
    });
    if (!changedText) {
      quotesA.insertBefore(document.createTextNode("📅 Reserves "), quotesA.firstChild);
    }
    quotesA.setAttribute('title', 'Reserves');
  }

  // 3) Arreglar text “Factures i amp; Factures” -> “🧾 Rebuts”
  const invoicesA = document.querySelector("a[href='/my/invoices']");
  if (invoicesA) {
    invoicesA.childNodes.forEach(n => {
      if (n.nodeType === Node.TEXT_NODE && n.nodeValue.trim()) {
        n.nodeValue = "🧾 Rebuts ";
      }
    });
    invoicesA.setAttribute('title', 'Rebuts');
  }

  // 4) Comandes de venda -> Comandes
  const ordersA = document.querySelector("a[href='/my/orders']");
  if (ordersA) {
    ordersA.childNodes.forEach(n => {
      if (n.nodeType === Node.TEXT_NODE && n.nodeValue.trim()) {
        n.nodeValue = "🛒 Comandes ";
      }
    });
    ordersA.setAttribute('title', 'Comandes');
  }
});
